import datetime
import json
import unittest

from records import to_json


class TestRecords(unittest.TestCase):
    def test_date_roundtrip(self):
        out = to_json({'name': 'a', 'when': datetime.date(2026, 10, 8)})
        parsed = json.loads(out)
        self.assertEqual(parsed['when'], '2026-10-08')

    def test_plain(self):
        self.assertEqual(json.loads(to_json({'n': 1})), {'n': 1})


if __name__ == '__main__':
    unittest.main()
